const net = require('net');
const { parseRequest } = require('./parser');
const { BAD_REQUEST_RESPONSE, PAYLOAD_TOO_LARGE_RESPONSE, routeRequest } = require('./router');

const PORT = process.env.PORT || 8080;

const readPositiveInteger = (name, defaultValue) => {
  const configuredValue = process.env[name] ?? defaultValue;
  const value = Number(configuredValue);
  if (!Number.isSafeInteger(value) || value <= 0) {
    throw new Error(`${name} must be a positive integer, got "${configuredValue}"`);
  }
  return value;
};

const LIMITS = {
  maxRequestLineBytes: readPositiveInteger('MAX_REQUEST_LINE_BYTES', 8192),
  maxHeaderBytes: readPositiveInteger('MAX_HEADER_BYTES', 16384),
  maxBodyBytes: readPositiveInteger('MAX_BODY_BYTES', 1048576),
};

const server = net.createServer((conn) => {
  let receivedBytes = Buffer.alloc(0);

  const sendResponse = (response) => conn.end(response, 'latin1');

  conn.on('error', () => {});
  conn.on('data', (chunk) => {
    if (conn.writableEnded) return;
    receivedBytes = Buffer.concat([receivedBytes, chunk]);

    const result = parseRequest(receivedBytes, LIMITS);
    if (result.state === 'complete') {
      sendResponse(routeRequest(result.request));
    } else if (result.state === 'invalid') {
      sendResponse(BAD_REQUEST_RESPONSE);
    } else if (result.state === 'too_large') {
      sendResponse(PAYLOAD_TOO_LARGE_RESPONSE);
    }
  });
  conn.on('end', () => {
    if (!conn.writableEnded) sendResponse(BAD_REQUEST_RESPONSE);
  });
});

server.listen(PORT);

